import os,glob,re,json

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G = load()

demo_in = G['Demo pair 1 input']
test_in = G['Test input']

# Compare patterns between demo input and test input
print("=== Test input analysis ===")
for i, row in enumerate(test_in):
    print(f"Row {i}: {row}")
    # Check for consecutive non-zero values
    non_zero_start = -1
    non_zero_run = 0
    for j, val in enumerate(row):
        if val != 0:
            if non_zero_start < 0:
                non_zero_start = j
            non_zero_run += 1
        else:
            if non_zero_run > 0:
                print(f"   Non-zero run: cols {non_zero_start} to {non_zero_start+non_zero_run-1}, length={non_zero_run}")
                non_zero_start = -1
                non_zero_run = 0
    if non_zero_run > 0:
        print(f"   Non-zero run: cols {non_zero_start} to {non_zero_start+non_zero_run-1}, length={non_zero_run}")

# Count non-zeros per row
print("\n=== Non-zero counts per row ===")
for i, row in enumerate(test_in):
    print(f"Row {i}: {sum(1 for v in row if v != 0)} non-zeros")

# Maybe the rule is about preserving shapes? Let me visualize the structure
print("\n=== Visualizing test input structure ===")
for i, row in enumerate(test_in):
    visual = ''.join(['#' if v != 0 else '.' for v in row])
    print(f"{visual}")

